class Solution { private fun maximumRow(mat:Array<IntArray>,col:Int):Int{var row=0;for(i in 1 until mat.size)if(mat[i][col]>mat[row][col])row=i;return row};fun findPeakGrid(mat:Array<IntArray>):IntArray{var left=0;var right=mat[0].lastIndex;while(left<right){val middle=(left+right)/2;val row=maximumRow(mat,middle);if(mat[row][middle]<mat[row][middle+1])left=middle+1 else right=middle};return intArrayOf(maximumRow(mat,left),left)} }
